class Solution {
  public long countNonDecreasingSubarrays(int[] nums, int k) {
    int n = nums.length;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    // S[i] = sum over j >= i of max(nums[i..j])
    long[] S = new long[n + 1];
    int[] stack = new int[n];
    int sp = 0;
    for (int i = n - 1; i >= 0; i--) {
      while (sp > 0 && nums[stack[sp - 1]] <= nums[i]) sp--;
      int ng = sp == 0 ? n : stack[sp - 1];
      S[i] = (long) nums[i] * (ng - i) + S[ng];
      stack[sp++] = i;
    }
    int LOG = 1;
    while ((1 << LOG) <= n) LOG++;
    int[][] sp2 = new int[LOG][];
    sp2[0] = new int[n];
    for (int i = 0; i < n; i++) sp2[0][i] = i;
    for (int j = 1; j < LOG; j++) {
      sp2[j] = new int[n];
      for (int i = 0; i + (1 << j) <= n; i++) {
        int a = sp2[j - 1][i], b = sp2[j - 1][i + (1 << (j - 1))];
        sp2[j][i] = nums[b] > nums[a] ? b : a;
      }
    }
    long ans = 0;
    int r = -1;
    for (int l = 0; l < n; l++) {
      if (r < l) r = l;
      while (r + 1 < n) {
        int len = r + 2 - l, j = 31 - Integer.numberOfLeadingZeros(len);
        int a = sp2[j][l], b = sp2[j][r + 2 - (1 << j)];
        int p = nums[b] > nums[a] ? b : a;
        long cost = S[l] - S[p] + (long) nums[p] * (r + 1 - p + 1) - (pre[r + 2] - pre[l]);
        if (cost > k) break;
        r++;
      }
      ans += r - l + 1;
    }
    return ans;
  }
}
